#!/usr/bin/env node
// Throwaway differential-test harness for test7 (ascii-random input class).
// Runs the Python reference executable and the Node port on IDENTICAL argv
// arrays and compares stdout / stderr / exit code byte-for-byte.

import { spawnSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const REF = '/workspace/dataset/test7_executable';
const PORT_ARGS = ['/output/test7.mjs'];

// ---------- deterministic PRNG (mulberry32) so the run is reproducible ----------
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(0xC0FFEE7);

const int = (n) => Math.floor(rnd() * n);
const pick = (arr) => arr[int(arr.length)];

// printable ASCII 0x20..0x7E
const PRINTABLE = Array.from({ length: 95 }, (_, i) => String.fromCharCode(0x20 + i));
// the punctuation-heavy alphabet the sample cases look like
const SAMPLEY = Array.from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789{}[]*,.!@#$%^&()_+-=;:<>?/|~');
const PUNCT = Array.from(' !"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~');

function randStr(len, alphabet = PRINTABLE) {
  let s = '';
  for (let i = 0; i < len; i++) s += pick(alphabet);
  return s;
}
// avoid a leading '-' so the value is not parsed as an option flag
function randStrNoDash(len, alphabet = PRINTABLE) {
  let s = randStr(len, alphabet);
  while (s.length && s[0] === '-') s = randStr(len, alphabet);
  return s;
}
const saltNNN = () => `salt_${String(int(1000000)).padStart(6, '0')}`;

// ---------- case construction ----------
const cases = [];
const add = (argv, tag) => cases.push({ argv, tag });

// 1-4: the four documented sample cases
add(['--a', 'Lm8qH}*x', '--b', 'salt_346554', '--c', 'Ad32jimv'], 'sample-1');
add(['--a', 'tgUa2lL[', '--b', 'salt_417146', '--c', 'KdjWSQgf'], 'sample-2');
add(['--a', '6gU{zJV7', '--b', 'GHqA33x7mMiuwdKg', '--c', 'salt_007229'], 'sample-3');
add(['--a', 'cFfq,.ur', '--b', 'MVhmK4fpPRqXGF9b', '--c', 'NQGqkURv'], 'sample-4');

// 20 cases in exactly the sample style: 8-char punct-heavy pass, salt_NNNNNN / 8-16 char salt
for (let i = 0; i < 20; i++) {
  const a = randStrNoDash(8, SAMPLEY);
  const b = rnd() < 0.5 ? saltNNN() : randStrNoDash(8 + int(9), SAMPLEY);
  const c = rnd() < 0.5 ? saltNNN() : randStrNoDash(8 + int(9), SAMPLEY);
  add(['--a', a, '--b', b, '--c', c], `sample-style-${i + 1}`);
}

// 12 cases sweeping short lengths 1..12 across all three fields
for (let n = 1; n <= 12; n++) {
  add(['--a', randStrNoDash(n), '--b', randStrNoDash(n), '--c', randStrNoDash(n)], `len-sweep-${n}`);
}

// 24 cases over a wide length spread (1..300), independent lengths per field
const LENS = [1, 2, 3, 5, 7, 8, 13, 16, 17, 19, 20, 21, 23, 24, 25, 31, 32, 33,
  40, 47, 55, 63, 64, 65, 100, 127, 128, 129, 150, 199, 200, 255, 256, 257, 299, 300];
for (let i = 0; i < 24; i++) {
  const la = pick(LENS), lb = pick(LENS), lc = pick(LENS);
  add(['--a', randStrNoDash(la), '--b', randStrNoDash(lb), '--c', randStrNoDash(lc)],
    `spread-${i + 1}-(${la},${lb},${lc})`);
}

// 8 cases at PBKDF2/HMAC-SHA1 block boundaries (key longer than the 64-byte
// HMAC block gets hashed down first) -- lengths 63/64/65/128 for the passphrase
for (const n of [63, 64, 65, 66, 127, 128, 129, 130]) {
  add(['--a', randStrNoDash(n), '--b', randStrNoDash(20), '--c', randStrNoDash(n)], `hmac-block-${n}`);
}

// 10 punctuation-only cases (whitespace, quotes, backslashes, shell metachars)
for (let i = 0; i < 10; i++) {
  add(['--a', randStrNoDash(1 + int(40), PUNCT), '--b', randStrNoDash(1 + int(40), PUNCT),
    '--c', randStrNoDash(1 + int(40), PUNCT)], `punct-only-${i + 1}`);
}

// 6 long-tail cases: very long passphrase, tiny salts and vice versa
for (let i = 0; i < 6; i++) {
  const big = randStrNoDash(200 + int(101));
  const tiny = randStrNoDash(1 + int(3));
  add(i % 2 === 0 ? ['--a', big, '--b', tiny, '--c', tiny + '!']
    : ['--a', tiny, '--b', big, '--c', randStrNoDash(300)], `long-tail-${i + 1}`);
}

// 6 structural cases: identical salts, salt equal to passphrase, single space, etc.
{
  const s = randStrNoDash(12);
  add(['--a', s, '--b', s, '--c', s], 'identical-all');
  add(['--a', randStrNoDash(9), '--b', 'dup', '--c', 'dup'], 'identical-salts');
  add(['--a', ' ', '--b', ' ', '--c', '  '], 'spaces');
  add(['--a', 'a b\tc', '--b', 'x  y', '--c', ' z '], 'inner-whitespace');
  add(['--a', randStrNoDash(30), '--b', '=', '--c', '=='], 'equals-salt');
  add(['--a', '~!@#$%^&*()_+', '--b', 'salt_000000', '--c', 'salt_999999'], 'punct-pass');
}

// 8 cases where a field legitimately begins with '-' (random printable ASCII
// really does produce these; both parsers must agree, error or not)
for (let i = 0; i < 8; i++) {
  const which = i % 3;
  const v = ['--a', '--b', '--c'];
  const argv = ['--a', randStrNoDash(6), '--b', randStrNoDash(6), '--c', randStrNoDash(6)];
  argv[2 * which + 1] = '-' + randStr(1 + int(6));
  add(argv, `leading-dash-${i + 1}-on-${v[which]}`);
}

// ---------- run ----------
function run(cmd, args, argv) {
  const r = spawnSync(cmd, [...args, ...argv], { maxBuffer: 64 * 1024 * 1024, timeout: 60000 });
  return {
    stdout: r.stdout ?? Buffer.alloc(0),
    stderr: r.stderr ?? Buffer.alloc(0),
    code: r.status,
    signal: r.signal,
    error: r.error ? String(r.error.message) : null,
  };
}

// argparse embeds prog = basename(argv[0]), which is inherently
// 'test7_executable' vs 'test7.mjs'. Normalize it so only real diffs surface.
function normProg(buf) {
  return buf.toString('binary').split('test7_executable').join('<PROG>')
    .split('test7.mjs').join('<PROG>');
}

const results = [];
let matched = 0;
const mismatches = [];

for (let i = 0; i < cases.length; i++) {
  const { argv, tag } = cases[i];
  const ref = run(REF, [], argv);
  const port = run('node', PORT_ARGS, argv);

  const outEq = ref.stdout.equals(port.stdout);
  const errRawEq = ref.stderr.equals(port.stderr);
  const errNormEq = normProg(ref.stderr) === normProg(port.stderr);
  const codeEq = ref.code === port.code;
  const sigEq = ref.signal === port.signal;

  const ok = outEq && errNormEq && codeEq && sigEq;
  if (ok) matched++;
  else mismatches.push({ index: i + 1, tag, argv, ref, port, outEq, errRawEq, errNormEq, codeEq, sigEq });

  results.push({ index: i + 1, tag, ok, outEq, errRawEq, errNormEq, codeEq,
    refCode: ref.code, portCode: port.code,
    refOut: ref.stdout.toString('utf8'), portOut: port.stdout.toString('utf8'),
    refErr: ref.stderr.toString('utf8'), portErr: port.stderr.toString('utf8'),
    argv });
}

const summary = {
  total: cases.length,
  matched,
  mismatched: mismatches.length,
  mismatches: mismatches.map((m) => ({
    index: m.index, tag: m.tag, argv: m.argv,
    stdoutEqual: m.outEq, stderrEqualNormalized: m.errNormEq, exitCodeEqual: m.codeEq,
    reference: { exitCode: m.ref.code, signal: m.ref.signal, stdout: m.ref.stdout.toString('utf8'), stderr: m.ref.stderr.toString('utf8') },
    port: { exitCode: m.port.code, signal: m.port.signal, stdout: m.port.stdout.toString('utf8'), stderr: m.port.stderr.toString('utf8') },
  })),
};

writeFileSync('/tmp/difftest7-results.json', JSON.stringify({ summary, results }, null, 2));
console.log(JSON.stringify(summary, null, 2));

// sanity: how many cases actually produced two hex lines (i.e. exercised PBKDF2)
const hexOk = results.filter((r) => /^[0-9a-f]{48}\n[0-9a-f]{48}\n$/.test(r.refOut)).length;
const errCases = results.filter((r) => r.refCode !== 0).length;
console.log(`\nrefProducedTwoHexLines=${hexOk}  refNonZeroExit=${errCases}  rawStderrIdentical=${results.filter(r=>r.errRawEq).length}`);

