#!/usr/bin/env node
// Batch 2: bulk pure-random printable-ASCII differential test.
// Usage: node difftest7-bulk.mjs <seed> <count>
import { spawnSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const seed = Number(process.argv[2] ?? 12345);
const count = Number(process.argv[3] ?? 120);

function mulberry32(s) {
  let a = s >>> 0;
  return () => { a = (a + 0x6d2b79f5) >>> 0; let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}
const rnd = mulberry32(seed);
const int = (n) => Math.floor(rnd() * n);
const P = Array.from({ length: 95 }, (_, i) => String.fromCharCode(0x20 + i));
function rs(len) { let s = ''; for (let i = 0; i < len; i++) s += P[int(95)]; return s; }
function rsNoDash(len) { let s = rs(len); while (s[0] === '-') s = rs(len); return s; }

function norm(b) {
  return b.toString('binary').split('test7_executable').join('<P>').split('test7.mjs').join('<P>');
}
const run = (cmd, pre, argv) => {
  const r = spawnSync(cmd, [...pre, ...argv], { maxBuffer: 64 << 20, timeout: 60000 });
  return { o: r.stdout ?? Buffer.alloc(0), e: r.stderr ?? Buffer.alloc(0), c: r.status, s: r.signal };
};

let matched = 0; const mism = []; const lensSeen = new Set(); let hexLines = 0;
for (let i = 0; i < count; i++) {
  // lengths uniformly spread over 1..300
  const la = 1 + int(300), lb = 1 + int(300), lc = 1 + int(300);
  lensSeen.add(la); lensSeen.add(lb); lensSeen.add(lc);
  const argv = ['--a', rsNoDash(la), '--b', rsNoDash(lb), '--c', rsNoDash(lc)];
  const ref = run('/workspace/dataset/test7_executable', [], argv);
  const port = run('node', ['/output/test7.mjs'], argv);
  const ok = ref.o.equals(port.o) && norm(ref.e) === norm(port.e) && ref.c === port.c && ref.s === port.s;
  if (/^[0-9a-f]{48}\n[0-9a-f]{48}\n$/.test(ref.o.toString())) hexLines++;
  if (ok) matched++;
  else mism.push({ index: i + 1, argv, lens: [la, lb, lc],
    reference: { exitCode: ref.c, signal: ref.s, stdout: ref.o.toString('utf8'), stderr: ref.e.toString('utf8') },
    port: { exitCode: port.c, signal: port.s, stdout: port.o.toString('utf8'), stderr: port.e.toString('utf8') } });
}
const out = { seed, total: count, matched, mismatched: mism.length,
  refProducedTwoHexLines: hexLines, distinctLengthsExercised: lensSeen.size,
  minLen: Math.min(...lensSeen), maxLen: Math.max(...lensSeen), mismatches: mism };
writeFileSync(`/tmp/difftest7-bulk-${seed}.json`, JSON.stringify(out, null, 2));
console.log(JSON.stringify(out, null, 2));

#!/usr/bin/env node
// Batch 3: 80 cases in the exact punctuation-heavy sample style
// ("Lm8qH}*x" / "salt_NNNNNN" / 8-16 char alnum salts), plus short lengths 1-16.
import { spawnSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';

function mulberry32(s){let a=s>>>0;return()=>{a=(a+0x6d2b79f5)>>>0;let t=a;
 t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);
 return((t^(t>>>14))>>>0)/4294967296;};}
const rnd=mulberry32(0xBADC0DE);
const int=n=>Math.floor(rnd()*n);
const A=Array.from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789');
const S=Array.from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789{}[]*,.!@#$%^&()_+=;:<>?/|~`\'"\\ ');
const rs=(n,al)=>{let s='';for(let i=0;i<n;i++)s+=al[int(al.length)];return s;};
const salt=()=>`salt_${String(int(1000000)).padStart(6,'0')}`;
const norm=b=>b.toString('binary').split('test7_executable').join('<P>').split('test7.mjs').join('<P>');
const run=(c,p,a)=>{const r=spawnSync(c,[...p,...a],{maxBuffer:64<<20,timeout:60000});
 return{o:r.stdout??Buffer.alloc(0),e:r.stderr??Buffer.alloc(0),c:r.status,s:r.signal};};

const cases=[];
for(let i=0;i<40;i++){                       // exact sample shape
  cases.push(['--a',rs(8,S),'--b',rnd()<0.5?salt():rs(8+int(9),A),'--c',rnd()<0.5?salt():rs(8+int(9),A)]);
}
for(let n=1;n<=16;n++){                      // every short length 1..16, twice
  cases.push(['--a',rs(n,S),'--b',rs(n,S),'--c',rs(n,S)]);
  cases.push(['--a',rs(n,S),'--b',salt(),'--c',rs(n,A)]);
}
for(let i=0;i<8;i++){                        // ascii-heavy mixed
  cases.push(['--a',rs(1+int(24),S),'--b',rs(1+int(24),S),'--c',rs(1+int(24),S)]);
}
// strip any accidental leading '-' (would be a parser test, covered elsewhere)
for(const c of cases) for(let i=1;i<c.length;i+=2) if(c[i][0]==='-') c[i]='x'+c[i].slice(1);

let matched=0;const mism=[];
cases.forEach((argv,i)=>{
  const ref=run('/workspace/dataset/test7_executable',[],argv);
  const port=run('node',['/output/test7.mjs'],argv);
  const ok=ref.o.equals(port.o)&&norm(ref.e)===norm(port.e)&&ref.c===port.c&&ref.s===port.s;
  if(ok)matched++;else mism.push({index:i+1,argv,
    reference:{exitCode:ref.c,stdout:ref.o.toString('utf8'),stderr:ref.e.toString('utf8')},
    port:{exitCode:port.c,stdout:port.o.toString('utf8'),stderr:port.e.toString('utf8')}});
});
const out={total:cases.length,matched,mismatched:mism.length,mismatches:mism};
writeFileSync('/tmp/difftest7-style.json',JSON.stringify(out,null,2));
console.log(JSON.stringify(out,null,2));
